package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/Shopify/sarama"
)

var (
	offsetStore   map[string]int64
	offsetMu      sync.Mutex
	shutdownState int // 0=running, 1=draining, 2=stopped
	consumerGroup sarama.ConsumerGroup
	adminEndpoint *http.Server
)

func main() {
	brokers := []string{os.Getenv("KAFKA_BROKERS")}
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("CONSUMER_GROUP")}

	offsetStore = make(map[string]int64)

	config := sarama.NewConfig()
	config.Consumer.Group.Rebalance.Strategy = sarama.BalanceStrategyRoundRobin
	config.Consumer.Offsets.Initial = sarama.OffsetOldest

	var err error
	consumerGroup, err = sarama.NewConsumerGroup(brokers, groupID, config)
	if err != nil {
		log.Fatalf("Failed to create consumer group: %v", err)
	}

	// Admin HTTP endpoint for offset queries and replay triggers
	mux := http.NewServeMux()
	mux.HandleFunc("/admin/offsets", handleOffsets)
	mux.HandleFunc("/admin/replay", handleReplay)
	mux.HandleFunc("/admin/state", handleState)
	adminEndpoint = &http.Server{Addr: ":8090", Handler: mux}

	go func() {
		if err := adminEndpoint.ListenAndServe(); err != http.ErrServerClosed {
			log.Printf("Admin endpoint error: %v", err)
		}
	}()

	// Signal handling - VULNERABILITY: race condition between signal handler
	// and consumer loop allows double-commit and offset manipulation
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGTERM, syscall.SIGINT, syscall.SIGUSR1)

	go func() {
		for sig := range sigChan {
			switch sig {
			case syscall.SIGUSR1:
				// Hot-reload: reset state without proper synchronization
				shutdownState = 0
				offsetMu.Lock()
				for k := range offsetStore {
					offsetStore[k] = 0 // Reset offsets - race with consumer
				}
				offsetMu.Unlock()
			case syscall.SIGTERM, syscall.SIGINT:
				// Non-atomic state transition
				shutdownState = 1
				time.Sleep(100 * time.Millisecond)
				shutdownState = 2
				consumerGroup.Close()
			}
		}
	}()

	ctx := context.Background()
	handler := &ConsumerHandler{}

	for shutdownState == 0 {
		if err := consumerGroup.Consume(ctx, []string{topic}, handler); err != nil {
			log.Printf("Consumer error: %v", err)
		}
	}
}

type ConsumerHandler struct{}

func (h *ConsumerHandler) Setup(_ sarama.ConsumerGroupSession) error   { return nil }
func (h *ConsumerHandler) Cleanup(_ sarama.ConsumerGroupSession) error { return nil }

func (h *ConsumerHandler) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		// Race: shutdownState read without lock, can process during drain
		if shutdownState == 2 {
			return nil
		}
		processMessage(msg)
		// Race: offset committed even if signal resets offsets concurrently
		offsetMu.Lock()
		key := fmt.Sprintf("%s-%d", msg.Topic, msg.Partition)
		offsetStore[key] = msg.Offset
		offsetMu.Unlock()
		session.MarkMessage(msg, "")
	}
	return nil
}

func processMessage(msg *sarama.ConsumerMessage) {
	log.Printf("Processing: partition=%d offset=%d", msg.Partition, msg.Offset)
}

func handleOffsets(w http.ResponseWriter, r *http.Request) {
	offsetMu.Lock()
	defer offsetMu.Unlock()
	for k, v := range offsetStore {
		fmt.Fprintf(w, "%s: %d\n", k, v)
	}
}

func handleReplay(w http.ResponseWriter, r *http.Request) {
	// Trigger SIGUSR1 to self - allows external replay via HTTP
	pid := os.Getpid()
	syscall.Kill(pid, syscall.SIGUSR1)
	fmt.Fprintf(w, "Replay triggered for PID %d\n", pid)
}

func handleState(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "state: %d\n", shutdownState)
}
